// Entire CLI extension for Pi
// Auto-generated by `entire enable --agent pi`
// Do not edit manually — changes will be overwritten on next install.
//
// Forwards Pi lifecycle events to `entire hooks pi <event>` so Entire can
// create checkpoints, capture transcripts, and offer rewind/resume.
//
// ENTIRE_CMD is replaced at install time by Entire's installer.

import { isToolCallEventType, type ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { execFile } from "node:child_process";
import { Type } from "typebox";
import { Check } from "typebox/value";

const InjectedContextSchema = Type.Object(
  { inject_context: Type.Optional(Type.String()) },
  { additionalProperties: true },
);

type SkillEvent = { skill_name: string; invocation: string; timestamp: string };
type EntireHookData = {
  type: "session_start" | "before_agent_start" | "agent_end" | "session_shutdown";
  cwd?: string;
  session_file?: string;
  prompt?: string;
  skill_events?: SkillEvent[];
};

export default function (pi: ExtensionAPI) {
  // Herdr-launched subagents receive this dedicated flag because they do not
  // inherit the Parent Pi's environment. Pi preserves extension flag values
  // across /reload, so the owning process keeps the same identity after reload.
  pi.registerFlag("entire-nested", {
    description: "Disable top-level Entire lifecycle hooks in a nested Pi",
    type: "boolean",
    default: false,
  });
  const nested = pi.getFlag("entire-nested") === true;

  const ENTIRE_CMD = 'entire';
  let pendingSkillEvents: SkillEvent[] = [];

  // fireHook pipes data to `entire hooks pi <hookName>` and resolves with the
  // hook's stdout (empty string on any failure). Most hooks ignore the return;
  // before_agent_start uses it to apply a model-context injection.
  function fireHook(hookName: string, data: EntireHookData): Promise<string> {
    return new Promise((resolve) => {
      try {
        const child = execFile(
          "sh",
          ["-c", `${ENTIRE_CMD} hooks pi ${hookName}`],
          { timeout: 10000, windowsHide: true, maxBuffer: 4 * 1024 * 1024 },
          (_err, stdout) => resolve(stdout),
        );
        child.stdin?.end(JSON.stringify(data));
      } catch {
        // best effort — never block the agent on a hook failure
        resolve("");
      }
    });
  }

  // parseInjectedContext scans a hook's stdout for Entire's injection envelope
  // ({"inject_context":"..."}) and returns the text to inject, or null.
  function parseInjectedContext(stdout: string): string | null {
    if (!stdout) return null;
    for (const line of stdout.split("\n")) {
      const trimmed = line.trim();
      if (!trimmed.startsWith("{")) continue;
      try {
        const parsed: unknown = JSON.parse(trimmed);
        if (Check(InjectedContextSchema, parsed) && parsed.inject_context) {
          return parsed.inject_context;
        }
      } catch {
        // not our envelope — ignore
      }
    }
    return null;
  }

  function parseSkillInvocation(text: string): { skill_name: string; invocation: string } | null {
    const match = text.trimStart().match(/^\/skill:([a-z0-9][a-z0-9-]{0,63})(?:\s|$)/);
    if (!match) return null;
    const invocation = text.trimStart().split(/\s+/, 1)[0] ?? `/skill:${match[1]}`;
    return { skill_name: match[1], invocation };
  }

  // Agent-driven bash subprocesses inherit a real TTY but cannot answer
  // hook prompts. Disable git/Entire terminal prompts for bash calls so
  // Entire treats agent-driven commits as non-interactive.
  //
  // Registered even when nested: a nested Pi is non-interactive by construction
  // while still inheriting the parent's TTY, and Entire's git hooks live in
  // .git/hooks independently of this extension, so a nested subagent that commits
  // needs this hardening at least as much as the parent does.
  pi.on("tool_call", async (event) => {
    if (!isToolCallEventType("bash", event) || event.input.command.includes("GIT_TERMINAL_PROMPT=")) {
      return;
    }
    event.input.command = "export GIT_TERMINAL_PROMPT=0\n" + event.input.command;
  });

  // Everything below forwards session lifecycle to Entire, which only the
  // top-level Pi may do.
  if (nested) return;

  pi.on("input", async (event) => {
    const skill = parseSkillInvocation(event.text);
    if (skill) {
      pendingSkillEvents.push({ ...skill, timestamp: new Date().toISOString() });
    }
    return { action: "continue" };
  });

  pi.on("session_start", async (_event, ctx) => {
    await fireHook("session_start", {
      type: "session_start",
      cwd: ctx.cwd,
      session_file: ctx.sessionManager.getSessionFile(),
    });
  });

  pi.on("before_agent_start", async (event, ctx) => {
    const skillEvents = pendingSkillEvents;
    pendingSkillEvents = [];
    const stdout = await fireHook("before_agent_start", {
      type: "before_agent_start",
      cwd: ctx.cwd,
      session_file: ctx.sessionManager.getSessionFile(),
      prompt: event.prompt,
      skill_events: skillEvents,
    });
    const injected = parseInjectedContext(stdout);
    if (injected) {
      // Inject a hidden, persistent message so the model learns about Entire.
      // display:false keeps it out of the user-facing transcript while still
      // sending it to the LLM. Entire emits this at most once per session.
      return {
        message: {
          customType: "entire-context",
          content: injected,
          display: false,
        },
      };
    }
  });

  pi.on("agent_end", async (_event, ctx) => {
    await fireHook("agent_end", {
      type: "agent_end",
      cwd: ctx.cwd,
      session_file: ctx.sessionManager.getSessionFile(),
    });
  });

  pi.on("session_shutdown", async () => {
    await fireHook("session_shutdown", { type: "session_shutdown" });
  });
}

    };
  }

  private async partialChild(
    request: StartChildRequest,
    location: ChildLocation,
    agentName: string,
  ): Promise<HostedChild> {
    try {
      return await this.hostedChild(
        request,
        location,
        agentName,
        await this.getAgent(new HerdrSocketClient(request.parent.socketPath), location.paneId),
      );
    } catch {
      return { taskId: request.taskId, sessionId: request.sessionId, location, agentName };
    }
  }

  private async getAgent(client: HerdrSocketClient, target: string, signal?: AbortSignal): Promise<AgentInfoResponse> {
    return parseAgentInfo(await client.call("agent.get", { target }, signal));
  }

  private async startWhenShellStable(
    client: HerdrSocketClient,
    paneId: string,
    params: HerdrRequestParameters,
    signal?: AbortSignal,
  ): Promise<void> {
    let stablePolls = 0;
    for (let attempt = 0; attempt < SHELL_READY_ATTEMPTS; attempt += 1) {
      let processInfo: PaneProcessInfo["process_info"];
      try {
        ({ process_info: processInfo } = parsePaneProcessInfo(
          await client.call("pane.process_info", { pane_id: paneId }, signal),
        ));
      } catch (error) {
        if (!(error instanceof HerdrProtocolError) || error.code !== "pane_not_found") throw error;
      }
      const foreground = processInfo?.foreground_processes;
      const shellIsStable =
        processInfo?.shell_pid !== null &&
        processInfo?.shell_pid !== undefined &&
        foreground?.length === 1 &&
        foreground[0]?.pid === processInfo.shell_pid;
      stablePolls = shellIsStable ? stablePolls + 1 : 0;
      if (stablePolls >= SHELL_STABLE_POLLS) {
        try {
          await client.call("agent.start", params, signal);
          return;
        } catch (error) {
          if (
            !(error instanceof HerdrProtocolError) ||
            !SHELL_READY_RETRY_CODES.has(error.code) ||
            attempt === SHELL_READY_ATTEMPTS - 1
          )
            throw error;
          stablePolls = 0;
        }
      }
      await delay(250, signal);
    }
    throw new HerdrProtocolError("start_timeout", "Herdr did not report a stable child shell");
  }

  private async waitForSession(
    client: HerdrSocketClient,
    paneId: string,
    signal?: AbortSignal,
  ): Promise<AgentInfoResponse> {
    for (let attempt = 0; attempt < 120; attempt += 1) {
      const info = await this.getAgent(client, paneId, signal);
      if (info.agent?.agent_session?.kind === "path" && info.agent.agent_session.value) return info;
      await delay(250, signal);
    }
    throw new HerdrProtocolError("start_timeout", "Herdr did not report the child Pi session path");
  }

  private async promptWhenRecognized(
    client: HerdrSocketClient,
    paneId: string,
    prompt: string,
    signal?: AbortSignal,
  ): Promise<PromptResult> {
    for (let attempt = 0; attempt < 60; attempt += 1) {
      try {
        return parsePromptResult(await client.call("agent.prompt", { target: paneId, text: prompt, wait: {} }, signal));
      } catch (error) {
        if (
          !(error instanceof HerdrProtocolError) ||
          !error.message.includes("not an active named agent") ||
          attempt === 59
        )
          throw error;
        await delay(500, signal);
      }
    }
    throw new HerdrProtocolError("start_timeout", "Herdr did not recognize the child Pi");
  }
}

async function writeRolePrompt(prompt: string): Promise<{ dir: string; path: string }> {
  const dir = await mkdtemp(join(tmpdir(), "pi-herdr-role-"));
  const path = join(dir, "prompt.md");
  await writeFile(path, `Child role instructions:\n${prompt}`, { encoding: "utf8", mode: 0o600 });
  return { dir, path };
}

function piArgs(request: StartChildRequest, rolePromptPath?: string): string[] {
  const args = [
    "--session-id",
    request.sessionId,
    "--name",
    childLabel(request),
    "--entire-nested",
    "--exclude-tools",
    "spawn_pi",
  ];
  if (request.context.model) args.push("--model", `${request.context.model.provider}/${request.context.model.id}`);
  if (request.context.thinkingLevel) args.push("--thinking", request.context.thinkingLevel);
  if (rolePromptPath) args.push("--append-system-prompt", rolePromptPath);
  return args;
}

function childLabel(request: StartChildRequest): string {
  const parent = request.context.parentLabel ?? request.parent.paneId;
